pub struct RankedMember {
    /// Parliament identity.
    pub id: MemberId,
    /// Latest stored name.
    pub name: String,
    /// Latest party label.
    pub party_name: String,
    /// Latest constituency or membership description.
    pub membership_from: String,
}
